import { useState, useEffect } from "react";
import axios from "axios";
import SearchBar from "../components/SearchBar";
import HouseCard from "../components/HouseCard";
import { Link } from "react-router-dom";

function Home() {
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const isAuthenticated = !!localStorage.getItem("userId");

  const handleSearch = async (location) => {
    setLoading(true);
    try {
      const res = await axios.get(
        `http://localhost:5000/search?location=${encodeURIComponent(location)}`
      );
      setResults(res.data);
    } catch (error) {
      console.error("Error fetching homes:", error);
      alert("Error fetching homes: " + error.message);
      setResults([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    handleSearch(""); // Fetch all homes initially
  }, []);

  return (
    <div
      className="min-h-screen bg-cover bg-center text-white"
      style={{ backgroundImage: "url(http://localhost:5000/home_gen.jpg)" }}
    >
      <h1 className="text-5xl text-center mt-32 text-shadow-lg">
        WELCOME TO NEST FINDER
      </h1>
      <SearchBar onSearch={handleSearch} />
      <div className="mt-10 flex flex-col items-center gap-4">
        {loading && (
          <div className="loading-spinner">
            <img src="https://i.gifer.com/ZZ5H.gif" alt="Loading..." />
          </div>
        )}
        {results.length === 0 && !loading && (
          <p className="text-lg">No homes found in that area.</p>
        )}
        {results.map((home) => (
          <HouseCard key={home.id} home={home} openChat={() => {}} />
        ))}
      </div>
      <nav className="mt-4 flex justify-center gap-4">
        <Link to="/" className="text-blue-400 hover:underline">
          Home
        </Link>
        {isAuthenticated && (
          <Link
            to={`/dashboard/${localStorage.getItem("userId")}`}
            className="text-blue-400 hover:underline"
          >
            Dashboard
          </Link>
        )}
        <Link to="/upload" className="text-blue-400 hover:underline">
          Upload
        </Link>
        <Link
          to="/login"
          onClick={() => {
            localStorage.removeItem("userId");
            localStorage.removeItem("full_name");
          }}
          className="text-blue-400 hover:underline"
        >
          Logout
        </Link>
      </nav>
    </div>
  );
}

export default Home;
